// NewGetAttributesResponseBody builds the HTTP response body from the result
// of the "get_attributes" endpoint of the "user" service.
func NewGetAttributesResponseBody(res *user.UserAttributesResult) *GetAttributesResponseBody {
	body := &GetAttributesResponseBody{
		UserID:      res.UserID,
		UserType:    res.UserType,
		RetrievedAt: res.RetrievedAt,
	}
	if res.Attributes != nil {
		body.Attributes = make(map[string]any, len(res.Attributes))
		for key, val := range res.Attributes {
			tk := key
			tv := val
			body.Attributes[tk] = tv
		}
	}
	if res.DerivedAttributes != nil {
		body.DerivedAttributes = make(map[string]any, len(res.DerivedAttributes))
		for key, val := range res.DerivedAttributes {
			tk := key
			tv := val
			body.DerivedAttributes[tk] = tv
		}
	}
	if res.AttributeMetadata != nil {
		body.AttributeMetadata = make(map[string]*AttributeMetadataResponseBody, len(res.AttributeMetadata))
		for key, val := range res.AttributeMetadata {
			tk := key
			if val == nil {
				body.AttributeMetadata[tk] = nil
				continue
			}
			body.AttributeMetadata[tk] = marshalUserAttributeMetadataToAttributeMetadataResponseBody(val)
		}
	}
	if res.FreshnessStatus != nil {
		body.FreshnessStatus = marshalUserFreshnessStatusToFreshnessStatusResponseBody(res.FreshnessStatus)
	}
	if res.CacheInfo != nil {
		body.CacheInfo = marshalUserCacheInfoToCacheInfoResponseBody(res.CacheInfo)
	}
	return body
}

